public long gridlandMetro(int n, int m, int k, int[][] track) {
    // Conceptual only — infeasible for large n, m.
    boolean[][] covered = new boolean[n][m];
    for (int[] t : track) {
        int r = t[0] - 1;
        for (int c = t[1] - 1; c <= t[2] - 1; c++) {
            covered[r][c] = true;
        }
    }
    long free = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (!covered[i][j]) free++;
        }
    }
    return free;
}

