public long gridlandMetro(int n, int m, int k, int[][] track) {
    Map<Integer, List<int[]>> rows = new HashMap<>();
    for (int[] t : track) {
        rows.computeIfAbsent(t[0], z -> new ArrayList<>())
            .add(new int[]{t[1], t[2]});
    }
    long covered = 0;
    for (List<int[]> segs : rows.values()) {
        segs.sort((a, b) -> Integer.compare(a[0], b[0]));
        int curStart = segs.get(0)[0];
        int curEnd = segs.get(0)[1];
        for (int i = 1; i < segs.size(); i++) {
            int[] s = segs.get(i);
            if (s[0] <= curEnd) {
                curEnd = Math.max(curEnd, s[1]);
            } else {
                covered += curEnd - curStart + 1;
                curStart = s[0];
                curEnd = s[1];
            }
        }
        covered += curEnd - curStart + 1;
    }
    return (long) n * m - covered;
}

