def gridland_metro(n: int, m: int, k: int, track: list[list[int]]) -> int:
    from collections import defaultdict
    rows: dict[int, list[tuple[int, int]]] = defaultdict(list)
    for r, c1, c2 in track:
        rows[r].append((c1, c2))
    covered = 0
    for segs in rows.values():
        segs.sort()
        cur_start, cur_end = segs[0]
        for s_start, s_end in segs[1:]:
            if s_start <= cur_end:
                cur_end = max(cur_end, s_end)
            else:
                covered += cur_end - cur_start + 1
                cur_start, cur_end = s_start, s_end
        covered += cur_end - cur_start + 1
    return n * m - covered

